const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageBreak } = require('docx');
const fs = require('fs');

const NAVY = "1A2332";
const GOLD = "B8924F";
const LIGHT_GOLD = "F5EDD8";
const GRAY = "4A4A4A";
const LIGHT_GRAY = "F4F1EC";

// Helper for section divider
const divider = () => new Paragraph({
  children: [new TextRun("")],
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 1 } },
  spacing: { before: 200, after: 200 }
});

const heading1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  children: [new TextRun({ text, color: NAVY, bold: true })],
  spacing: { before: 360, after: 180 }
});

const heading2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  children: [new TextRun({ text, color: NAVY, bold: true })],
  spacing: { before: 280, after: 140 }
});

const heading3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  children: [new TextRun({ text: text.toUpperCase(), color: GOLD, bold: true, size: 22 })],
  spacing: { before: 240, after: 120 }
});

const body = (text, opts = {}) => new Paragraph({
  children: [new TextRun({ text, color: GRAY, ...opts })],
  spacing: { before: 80, after: 80, line: 300 }
});

const bodyBold = (text) => new Paragraph({
  children: [new TextRun({ text, color: NAVY, bold: true })],
  spacing: { before: 100, after: 80 }
});

const script = (text) => new Paragraph({
  children: [new TextRun({ text, italics: true, color: NAVY })],
  spacing: { before: 100, after: 100, line: 320 },
  indent: { left: 360 }
});

const bullet = (text, bold = false) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  children: [new TextRun({ text, color: GRAY, bold })],
  spacing: { before: 60, after: 60 }
});

const calloutBox = (label, content) => {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            margins: { top: 200, bottom: 200, left: 240, right: 240 },
            borders: {
              top: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              left: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              right: { style: BorderStyle.SINGLE, size: 12, color: GOLD }
            },
            children: [
              new Paragraph({
                children: [new TextRun({ text: label.toUpperCase(), bold: true, color: GOLD, size: 20 })],
                spacing: { after: 100 }
              }),
              new Paragraph({
                children: [new TextRun({ text: content, color: NAVY, italics: true, size: 24 })],
                spacing: { line: 320 }
              })
            ]
          })
        ]
      })
    ]
  });
};

const scriptBox = (content, color = LIGHT_GRAY) => {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: color, type: ShadingType.CLEAR },
            margins: { top: 180, bottom: 180, left: 240, right: 240 },
            borders: {
              top: { style: BorderStyle.NONE },
              bottom: { style: BorderStyle.NONE },
              left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
              right: { style: BorderStyle.NONE }
            },
            children: content.map(line =>
              new Paragraph({
                children: [new TextRun({ text: line, color: NAVY, size: 22 })],
                spacing: { before: 60, after: 60, line: 300 }
              })
            )
          })
        ]
      })
    ]
  });
};

const objectionBlock = (objection, response) => [
  new Paragraph({
    children: [new TextRun({ text: "OBJECTION: ", bold: true, color: GOLD, size: 20 }),
               new TextRun({ text: objection, bold: true, color: NAVY, size: 22 })],
    spacing: { before: 240, after: 100 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "RESPONSE:", bold: true, color: GOLD, size: 20 })],
    spacing: { before: 80, after: 60 }
  }),
  scriptBox(response)
];

// Build document content
const children = [
  // Title block
  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", color: GOLD, bold: true, size: 22 })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 100 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Referral Partner Script System", color: NAVY, bold: true, size: 44 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 100 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Outreach flow, qualification, objection handling", color: GRAY, italics: true, size: 22 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 240 }
  }),
  divider(),

  // Intro / How to use
  heading1("How to use this script"),
  body("This is a conversational framework, not a pitch. Your job is to open a door, ask honest questions, and invite the right owners to a no-pressure conversation. The team at Luxora handles the rest."),
  body("Read each section once before your first outreach. Do not memorize it word for word. Internalize the flow, then sound like yourself."),

  bodyBold("The core principle:"),
  calloutBox("Remember", "You are not selling Luxora. You are introducing a med spa owner to someone who can see what they cannot."),

  // Who we target
  heading1("Who you are targeting"),
  body("Only reach out to owners who fit this profile. Luxora is not a fit for everyone, and trying to force it costs you credibility."),
  bullet("Independent med spa owners (decision-makers only, not associates or front desk)", false),
  bullet("Practices generating $500K to $2M annually", false),
  bullet("Open at least 18 months (not brand new)", false),
  bullet("Owners who care about scaling, not just keeping the lights on", false),
  bullet("US-based practices", false),

  body("Skip these. They will waste your time and Bethany Anne's.", { bold: true, color: NAVY }),
  bullet("Solo injectors with no team or location", false),
  bullet("Practices doing under $300K (too early)", false),
  bullet("Owners actively looking for a buyer or winding down", false),
  bullet("Anyone who only wants a marketing agency", false),

  new Paragraph({ children: [new PageBreak()] }),

  // The Flow
  heading1("The 5-step outreach flow"),

  heading3("Step 1: Open the conversation"),
  body("Lead with curiosity, not a pitch. The goal of message one is a reply, nothing more."),
  scriptBox([
    "Hey [Name], quick question for you.",
    "",
    "I work alongside a team that partners with independent med spa owners on revenue growth, not ads, the actual business engine behind it. They've been mapping out a few practices in your area and yours kept coming up as one that's clearly built something real.",
    "",
    "Out of curiosity, how have things been feeling lately? Steady, or a bit up and down between months?"
  ]),

  body("Why this works: It compliments without flattering. It signals you have done research. It ends with a real question that invites a real answer."),

  heading3("Step 2: Listen and qualify"),
  body("When they reply, do not jump to the pitch. Ask one more question to understand where the friction actually lives."),
  scriptBox([
    "That tracks with what we're seeing across the board right now. Most owners I talk to say the lead flow is fine, it's everything that happens after that feels inconsistent.",
    "",
    "When you think about your business right now, where does it actually break down for you most often?",
    "",
    "Is it getting consults booked, getting people to show, closing the consult, or keeping clients coming back beyond the first treatment?"
  ]),

  calloutBox("Critical", "Stop talking. Let them tell you. The answer they give you is the exact angle Bethany Anne will lead with on the call."),

  heading3("Step 3: Bridge to the real problem"),
  body("Now you reframe what they said. You are not pitching Luxora yet. You are putting language around the gap they just described."),
  scriptBox([
    "Yeah, that's exactly the pattern we keep running into.",
    "",
    "Almost no one I talk to actually has a lead problem. The revenue is leaking somewhere between lead and booking, booking and consult, or consult and long-term retention. And most owners can't see it from inside the business because they're the one running it.",
    "",
    "The team I work with specializes in mapping exactly where that's happening and tightening the system so the business stops depending on the owner being in every transaction."
  ]),

  heading3("Step 4: Soft introduction (only if they're engaged)"),
  body("If they have responded twice with real answers, they are warm. Offer the next step as low-friction value, not a sales call."),
  scriptBox([
    "If you're open to it, I can connect you with them for what they call a Revenue Leak Review. It's not a sales call. They actually walk you through what they'd see in your specific market and where the biggest revenue gaps usually live in a practice your size.",
    "",
    "Worst case, you walk away with a sharper view of your own numbers. Best case, you find the leak that's been costing you for the last year.",
    "",
    "Want me to send the link?"
  ]),

  heading3("Step 5: Send the link"),
  scriptBox([
    "Perfect. Here you go: [INSERT YOUR REFERRAL LINK]",
    "",
    "Grab whatever time works. Bethany Anne (the founder) personally runs these. She's been in medical aesthetics for over a decade and has actually built and operated practices, so she'll speak your language.",
    "",
    "Let me know how it goes."
  ]),

  new Paragraph({ children: [new PageBreak()] }),

  // FAQ Section
  heading1("If they ask: who is this?"),
  body("Use this language. Do not improvise on credentials."),
  scriptBox([
    "The team is The Luxora Collective. The website is theluxoracollective.co.",
    "",
    "It's led by Bethany Anne, Co-Founder and CEO. She's spent over a decade in medical aesthetics, both inside multi-location practices on the operations side and on the growth side. She's built and managed med spas herself, which is why Luxora doesn't sound like a typical agency.",
    "",
    "Her business partner Eric is the CFO and runs the financial side, and they have a full team handling tech, paid traffic, content, and client delivery. It's not a one-person shop."
  ]),

  heading1("If they ask: what do they actually do?"),
  body("Lead with what Luxora does NOT do. That separates her from every agency in the owner's inbox."),
  scriptBox([
    "Honestly, the easiest way to describe it is what they don't do. They're not a marketing agency. They don't run ads as their main offer, they don't sell leads, and they don't try to bolt new traffic onto a business that isn't ready for it.",
    "",
    "What they actually do is work inside-out. They start with a Revenue Leak Audit, which finds the money that's already being lost in the business: undertrained front desk staff, unconverted consults, stagnant clients who never come back, missing memberships, weak package architecture. Most practices recover six figures here before any new marketing spend.",
    "",
    "Then they build a Market Blueprint specific to that practice and that city, so any future investment is based on actual data, not guesses.",
    "",
    "Once the foundation is solid, they install the full Growth Engine: staff sales training, memberships, package and upsell architecture, AI follow-up, CRM, reputation engine, partnership frameworks, and LTV systems.",
    "",
    "It's a done-with-you model. They don't take the keys, they teach the owner and the team how to run it. Most clients work with them for a year or longer."
  ]),

  heading1("Simpler version (if they want a one-liner)"),
  scriptBox([
    "Luxora finds where med spas are leaking revenue and builds the systems so bookings, conversions, and client retention all run predictably without the owner being in every transaction."
  ]),

  new Paragraph({ children: [new PageBreak()] }),

  // OBJECTIONS
  heading1("Objection handling"),
  body("These are the real objections you will get. Memorize the structure: acknowledge, reframe, redirect to the conversation. Never argue. Never defend."),

  ...objectionBlock(
    "I already have a marketing agency.",
    [
      "Totally fair, and most of the owners they work with do too.",
      "",
      "Luxora isn't an agency, so there's no overlap. Your agency runs traffic. Luxora fixes what happens to that traffic once it hits your business: the front desk handoff, consult conversion, package structure, follow-up, retention. Without that piece, even great ad spend leaks.",
      "",
      "The Revenue Leak Review actually shows you whether your agency's traffic is being maximized or wasted. Either answer is useful."
    ]
  ),

  ...objectionBlock(
    "How much does this cost?",
    [
      "I won't quote pricing because it depends on the size of the practice and what the audit actually surfaces. But I can tell you this: the Revenue Leak Review is free, and Bethany Anne is upfront on the call about what an engagement looks like.",
      "",
      "She works with practices in the $500K to $2M range, and the engagement is built to pay for itself out of revenue she helps recover from leaks already in the business. If it doesn't pencil out for your numbers, she'll tell you on the call."
    ]
  ),

  ...objectionBlock(
    "I don't have time for another call.",
    [
      "Get it. The Revenue Leak Review is 45 minutes, and you walk away with a real diagnostic of your business whether you ever work with her or not.",
      "",
      "Most owners tell me the call itself was the most clarity they've had on their own numbers in a year. Worst case, you spend 45 minutes and learn something. Best case, you find the leak that's been costing you all year."
    ]
  ),

  ...objectionBlock(
    "Send me some info first.",
    [
      "I could, but honestly the website won't tell you what's actually happening inside your specific practice. The whole point of the Revenue Leak Review is that it's tailored to your numbers and your market, not a generic deck.",
      "",
      "If you want the short version, the site is theluxoracollective.co. But the call is where you actually find out if it's a fit."
    ]
  ),

  ...objectionBlock(
    "We're slammed right now, can you reach out in a few months?",
    [
      "Hear you. Quick question though, are you slammed because you're booked solid, or slammed because the systems aren't running without you?",
      "",
      "If it's the second one, that's literally what Luxora fixes. Waiting three months usually just means three more months of the same problem. The audit doesn't take any of your time, Bethany Anne does the work and walks you through it. Worth 45 minutes to find out."
    ]
  ),

  ...objectionBlock(
    "I've tried consultants before, didn't work.",
    [
      "Yeah, that's a common one, and most of the time it's because the consultant gave a 60-page strategy doc and disappeared. Luxora is built the opposite way.",
      "",
      "It's done-with-you. They install the systems alongside your team, train your staff, and stay in the business for at least a year. The goal is for you to own the playbook at the end, not to keep paying them forever.",
      "",
      "Bethany Anne has actually run med spas herself, so she's not theorizing. The Revenue Leak Review will show you immediately whether her approach is different from what you've seen before."
    ]
  ),

  ...objectionBlock(
    "Is this just for big practices?",
    [
      "Actually the opposite. Luxora is specifically built for independent practices in the $500K to $2M range. Bigger groups have in-house teams. Solo injectors aren't ready yet. The owners she works best with are the ones who've built something real but feel like the business depends on them being in every consult, every decision, every fire."
    ]
  ),

  ...objectionBlock(
    "Why should I trust her over [other coach or guru in the space]?",
    [
      "Honestly, you shouldn't trust anyone before a real conversation. That's the point of the Revenue Leak Review. You'll know inside 45 minutes whether she actually understands the business or whether she's running the same script everyone else runs.",
      "",
      "What I can tell you is she's been operating inside med spas for over a decade, not just teaching about them, and she has a real team behind her. That's usually the first filter most owners are looking for."
    ]
  ),

  ...objectionBlock(
    "What if I just want to know what she'd do for me without committing?",
    [
      "That's exactly what the Revenue Leak Review is for. There's no commitment on the call. She walks you through what she'd see in your business, where the gaps usually are for a practice your size, and what fixing them would look like. If it makes sense to keep talking, you keep talking. If not, you keep the diagnostic."
    ]
  ),

  new Paragraph({ children: [new PageBreak()] }),

  // Rules
  heading1("Rules of engagement"),

  heading3("Do this"),
  bullet("Keep every message conversational. Read it out loud before sending. If it sounds like a brochure, rewrite it.", false),
  bullet("Let the owner talk more than you. Two questions for every one statement.", false),
  bullet("Position yourself as a peer with a useful introduction, not a salesperson.", false),
  bullet("Only send the booking link after they have shown clear interest.", false),
  bullet("Use the owner's exact language back to them when you bridge to Luxora.", false),
  bullet("Reference Bethany Anne by name once she comes up. It humanizes the introduction.", false),

  heading3("Do not do this"),
  bullet("Do not quote pricing. Ever. That conversation belongs on the call with Bethany Anne.", false),
  bullet("Do not over-explain. If you find yourself writing a third paragraph, delete it.", false),
  bullet("Do not push. If they go cold after two messages, move on. Pressure kills the referral.", false),
  bullet("Do not promise specific results, percentages, or timelines.", false),
  bullet("Do not pitch the Growth Engine, packages, memberships, or systems on the front end. That is the call.", false),
  bullet("Do not use the word agency to describe Luxora. It is not one.", false),

  divider(),

  heading1("Quick reference cheat sheet"),

  body("If you only remember six things, remember these.", { bold: true, color: NAVY }),
  bullet("Open with curiosity, not a pitch.", true),
  bullet("Ask where the business breaks down. Listen.", true),
  bullet("Reframe their answer as a revenue leak, not a marketing problem.", true),
  bullet("Offer the Revenue Leak Review as diagnostic, not sales.", true),
  bullet("Send the link only when they ask or clearly want it.", true),
  bullet("Bethany Anne, Co-Founder and CEO. theluxoracollective.co. Done-with-you. Not an agency.", true),

  new Paragraph({
    children: [new TextRun({ text: " ", color: NAVY })],
    spacing: { before: 400 }
  }),

  new Paragraph({
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", color: GOLD, bold: true, size: 18 })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 200 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "theluxoracollective.co", color: NAVY, size: 18 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 80 }
  }),
  new Paragraph({
    children: [new TextRun({ text: "Internal use. For referral partners only.", color: GRAY, italics: true, size: 16 })],
    alignment: AlignmentType.CENTER
  })
];

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Calibri", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Calibri", color: NAVY },
        paragraph: { spacing: { before: 360, after: 180 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Calibri", color: NAVY },
        paragraph: { spacing: { before: 280, after: 140 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 22, bold: true, font: "Calibri", color: GOLD },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 2 } }
    ]
  },
  numbering: {
    config: [
      { reference: "bullets",
        levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_Referral_Partner_Script.docx", buffer);
  console.log("Document created successfully");
});

